import { analisarGcode } from '../src/utils/fatiador/gcode';

/**
 * Recorte com a mesma forma do ficheiro real do motor: cabeçalho, PRINT_START,
 * PRINT_END a fechar o bloco executável, resumo e bloco de configuração.
 * Valores copiados do cubo20.gcode de 2026-11-21.
 */
const COMPLETO = [
  '; HEADER_BLOCK_START',
  '; generated by ElegooSlicer 1.5.3-android',
  '; total layer number: 100',
  '; filament_density: 1.25',
  '; HEADER_BLOCK_END',
  '',
  '; EXECUTABLE_BLOCK_START',
  'EXCLUDE_OBJECT_DEFINE NAME=cubo20.stl_id_0_copy_0 CENTER=128,128',
  ';TYPE:Custom',
  'SET_PRINT_STATS_INFO TOTAL_LAYER=100',
  '',
  'PRINT_START EXTRUDER=210 BED=60 CHAMBER=0 TOOL=0',
  'G90',
  'G21',
  ';LAYER_CHANGE',
  ';Z:0.2',
  'G1 X118.807 Y137.193 E.66',
  ';LAYER_CHANGE',
  'G1 X137.193 Y118.807 E.66',
  'EXCLUDE_OBJECT_END NAME=cubo20.stl_id_0_copy_0',
  '; filament end gcode ',
  'PRINT_END',
  'M73 P100 R0',
  '; EXECUTABLE_BLOCK_END',
  '',
  '; filament used [g] = 3.47',
  '; total filament used [g] = 3.47',
  '; total layers count = 100',
  '; estimated printing time (normal mode) = 8m 43s',
  '',
  '; CONFIG_BLOCK_START',
  '; filament_type = PLA',
  '; filament_settings_id = "Elegoo PLA @ECC"',
  '; machine_end_gcode = PRINT_END',
  '; CONFIG_BLOCK_END',
].join('\n');

const bytes = (texto: string) => Buffer.byteLength(texto, 'utf8');

describe('analisarGcode', () => {
  it('recusa um ficheiro vazio', () => {
    const r = analisarGcode('', 0);
    expect(r.valido).toBe(false);
    expect(r.motivo).toBe('vazio');
    expect(r.camadas).toBe(0);
  });

  it('recusa um ficheiro cortado, sem PRINT_END', () => {
    const cortado = COMPLETO.replace(/PRINT_END\n/, '').replace(
      /; (EXECUTABLE|CONFIG)_BLOCK_(START|END).*\n?/g,
      ''
    );
    const r = analisarGcode(cortado, bytes(cortado));
    expect(r.valido).toBe(false);
    expect(r.motivo).toBe('sem_print_end');
  });

  it('recusa um ficheiro cujo fim não é o marcador do bloco', () => {
    const semFim = COMPLETO.replace('; CONFIG_BLOCK_END', 'G1 X1 Y1 E.1');
    const r = analisarGcode(semFim, bytes(semFim));
    expect(r.valido).toBe(false);
    expect(r.motivo).toBe('sem_fim');
  });

  it('aceita o ficheiro completo e devolve o que o ecrã mostra', () => {
    const r = analisarGcode(COMPLETO, bytes(COMPLETO));
    expect(r.valido).toBe(true);
    expect(r.motivo).toBeUndefined();
    expect(r.bytes).toBe(bytes(COMPLETO));
    expect(r.camadas).toBe(100);
    expect(r.bico).toBe(210);
    expect(r.mesa).toBe(60);
    expect(r.tempo).toBe('8m 43s');
    expect(r.gramas).toBe(3.47);
    expect(r.filamento).toBe('PLA');
    expect(r.perfilFilamento).toBe('Elegoo PLA @ECC');
  });

  it('não confunde o PRINT_END do bloco de configuração com o comando', () => {
    // Sem o comando no corpo, a menção em `machine_end_gcode` não serve de prova.
    const semComando = COMPLETO.replace(/\nPRINT_END\n/, '\n\n');
    const r = analisarGcode(semComando, bytes(semComando));
    expect(r.valido).toBe(false);
    expect(r.motivo).toBe('sem_print_end');
  });
});
